            # choose the i-th available 2 in that row; when the row has fewer
            # cells, use its rightmost available cell.
            avail = sorted(c for r, c in pts if r == target_r)
            if not avail:
                avail = sorted(c for r, c in pts)
            if avail:
                out[target_r][avail[min(i, len(avail)-1)]] = 8

