    pitch = 5 if max(h, w) >= 15 else 4
    starts_r = list(range(0, h - 3, pitch))
    starts_c = list(range(0, w - 3, pitch))
    nrows, ncols = len(starts_r), len(starts_c)
    occ = {}
    for i, r0 in enumerate(starts_r):
        for j, c0 in enumerate(starts_c):
            if any(grid[r][c] == 2 for r in range(r0, min(r0+4,h))
                   for c in range(c0, min(c0+4,w))):
                occ[(i,j)] = True

    # Clear the separator.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    # Complete the missing slot in the bar from the pattern on the same line.
    bar_rows = [r for r in range(h) if any(grid[r][c] == 3 for c in range(w))]
    bar_cols = [c for c in range(w) if any(grid[r][c] == 3 for r in range(h))]
    target = None
    if bar_rows and len(bar_rows) >= 3 and len(bar_rows) == max(bar_rows)-min(bar_rows)+1:
        i = min(bar_rows) // pitch
        # Fill the column shared by the occupied slots immediately above/below.
        if 0 < i < nrows-1:
            for j in range(ncols):
                if occ.get((i-1,j)) and occ.get((i+1,j)):
                    target = (i,j)
                    break
        # For a horizontal mask, the selected column can be represented
        # on both sides even if one adjacent cell is obscured by other blank space.
        if target is None and 0 < i < nrows-1:
            common = [j for j in range(ncols) if occ.get((i-1,j)) and occ.get((i+1,j))]
            if common: target = (i, common[0])
    elif bar_cols and len(bar_cols) >= 3 and len(bar_cols) == max(bar_cols)-min(bar_cols)+1:
        j = min(bar_cols) // pitch
        # The row containing the repeated leftmost pattern but lacking the
        # intervening slot is continued into the masked right-hand slot.
        for i in range(nrows):
            if occ.get((i,0)) and not occ.get((i,1)):
                target = (i,j)
                break

    if target is not None:
        ti, tj = target
        r0, c0 = starts_r[ti], starts_c[tj]
